        BafiLeadrRequest leadReq = new BafiLeadrRequest();
        leadReq.token = loginResp.token;
        leadReq.sessionId = configuration.GetSection("BafiParams").GetSection("sessionid").Value;
        leadReq.user_lead_id = loginResp.user_lead_id;

        leadReq.source = 2;
        if(user.LeadId!=null && user.LeadId.Trim()!="")
        {
            try
            {
                leadReq.source = int.Parse(user.LeadId);
            }
            catch(Exception leadid)
            {

            }
        }
        leadReq.user_id = int.Parse(configuration.GetSection("BafiParams").GetSection("user_id").Value);
        leadReq.project = configuration.GetSection("BafiParams").GetSection("project").Value;
        leadReq.leads = new List<BafiLeadItem>();
        BafiLeadItem lead = new BafiLeadItem();
        lead.ins_type = "other";

        if (product.fullName != null)
        {
            var clientName = product.fullName.Trim().Split(" ");
            if (clientName.Length > 0)
            {
                lead.first_name = clientName[0];
            }
            if (clientName.Length > 1)
            {
                lead.last_name = clientName[1];
            }
            lead.identification_number = product.id;
            lead.birthday = product.birthDate;
            lead.mobile = product.phone;
            lead.street = product.street;
            lead.city = product.city;
            lead.zip = product.zip;
            lead.email = product.email;

            lead.occupation = product.occupation;

            lead.date_start = DateTime.Now.ToString("dd-MM-yyyy");
            if (user.Fullname != null && user.Fullname.Trim() != "")
            {
                lead.salesman = user.Fullname;
            }
            leadReq.leads.Add(lead);
            BafiLeadResponce resp = await OpenLead(leadReq);
            if (resp.success)
            {
                return "Done";
            }
        }
        else
        {
            return "Lead has no name";
        }
    }
    return "Error Connecting";
